using UnityEngine;

namespace Game.Rendering
{
    /// <summary>
    /// ADR 0192: lit windows at dusk / night. Writes the globals of KamionNightWindows.hlsl from the sun elevation of
    /// the active lighting preset and binds the night data of the building atlases (Resources/Night, generated by
    /// art-source/world/materials/_src/night_facade.py).
    /// Shares of lit windows (WORKING_VALUE, no survey; to be judged against owner photos of Białystok blocks):
    /// - switch-on: people turn the light on as the room darkens, before the street lamps (sun 4° → −2°), progressive
    ///   per window (the shader compares a fixed per-window hash with share × on: windows come on one by one);
    /// - flats 0.40 at the end of civil twilight (−6°) → 0.50 later in the evening (−16°);
    /// - offices 0.65 at the end of civil twilight (a November 16:00 dusk is still working time) → 0.15 at night;
    /// - halls 0.45 → 0.30 (shift work), stairwells 0.35 (time switches / motion sensors).
    /// Luminance of a lit window (room behind glass / curtain): 15 cd/m² mean, WORKING_VALUE (lit interiors 100–300 lx
    /// on surfaces of reflectance 0.3–0.6 give 10–60 cd/m²), × exposure → display units.
    /// </summary>
    public static class NightWindows
    {
        public const float MeanLuminance = 15f;
        static readonly int k_Windows = Shader.PropertyToID("_KamionWindows"), k_Lum = Shader.PropertyToID("_KamionWindowsLum"),
            k_AtlasId = Shader.PropertyToID("_KamionNightAtlasId"), k_AtlasT = Shader.PropertyToID("_KamionNightAtlasT"),
            k_FarId = Shader.PropertyToID("_KamionNightFarId"), k_FarT = Shader.PropertyToID("_KamionNightFarT");
        static bool s_Bound, s_Applied;
        static float s_LastElevation, s_LastExposure;

        /// <summary>After a tier change (nightWindowsOff).</summary>
        public static void Reapply() { if (s_Applied) Apply(s_LastElevation, s_LastExposure); }
        static Texture2D[] s_Tex;      // held: shader globals do not keep Resources assets alive
        /// <summary>Night data textures bound (4 when the Resources/Night set loaded).</summary>
        public static int BoundTextures => s_Tex?.Length ?? 0;

        /// <summary>Last shares written (x flat, y office, z hall, w stairwell), already × switch-on.</summary>
        public static Vector4 Shares { get; private set; }
        /// <summary>0..1 switch-on of the last apply.</summary>
        public static float On { get; private set; }

        /// <summary>0..1: share of rooms that have switched the light on, from the true sun elevation (degrees).</summary>
        public static float SwitchOn(float elevationDeg) => Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(4f, -2f, elevationDeg));

        /// <summary>Shares of lit windows per class before the switch-on (x flat, y office, z hall, w stairwell).</summary>
        public static Vector4 BaseShares(float elevationDeg)
        {
            float late = Mathf.Clamp01((-6f - elevationDeg) / 10f);
            return new Vector4(Mathf.Lerp(0.40f, 0.50f, late), Mathf.Lerp(0.65f, 0.15f, late), Mathf.Lerp(0.45f, 0.30f, late), 0.35f);
        }

        /// <summary>EnvironmentLighting: after the exposure of the preset is known.</summary>
        public static void Apply(float elevationDeg, float exposure)
        {
            s_LastElevation = elevationDeg; s_LastExposure = exposure; s_Applied = true;
            bool tierOff = QualityProfileApplier.HasCurrent && QualityProfileApplier.Current.nightWindowsOff;
            On = tierOff ? 0f : SwitchOn(elevationDeg);
            Shares = BaseShares(elevationDeg) * On;
            if (On > 0f) Bind();
            Shader.SetGlobalVector(k_Windows, Shares);
            Shader.SetGlobalVector(k_Lum, new Vector4(MeanLuminance * exposure, On > 0f && s_Bound ? 1f : 0f, 0f, 0f));
        }

        static void Bind()
        {
            if (s_Bound) return;
            var aId = Resources.Load<Texture2D>("Night/T_NightAtlasId");
            var aT = Resources.Load<Texture2D>("Night/T_NightAtlasT");
            var fId = Resources.Load<Texture2D>("Night/T_NightFarId");
            var fT = Resources.Load<Texture2D>("Night/T_NightFarT");
            if (aId == null || aT == null || fId == null || fT == null)
            {
                Debug.LogWarning("[NightWindows] Resources/Night textures missing - run art-source/world/materials/_src/night_facade.py");
                return;
            }
            s_Tex = new[] { aId, aT, fId, fT };
            Shader.SetGlobalTexture(k_AtlasId, aId);
            Shader.SetGlobalTexture(k_AtlasT, aT);
            Shader.SetGlobalTexture(k_FarId, fId);
            Shader.SetGlobalTexture(k_FarT, fT);
            // LOAD_TEXTURE2D needs the texel grid; _TexelSize is not filled in for global textures
            Shader.SetGlobalVector("_KamionNightAtlasId_TexelSize", new Vector4(1f / aId.width, 1f / aId.height, aId.width, aId.height));
            Shader.SetGlobalVector("_KamionNightFarId_TexelSize", new Vector4(1f / fId.width, 1f / fId.height, fId.width, fId.height));
            s_Bound = true;
        }
    }
}
